/**
 * Direct sub-issues that are still live, oldest first (creation time, then
 * issue number). Archived children are omitted; their own children are not
 * pulled up into this list.
 */
export async function listChildIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/**
 * Every issue below `issueId` at any depth, archived or not. Walks through
 * archived nodes so a live grandchild under an archived child is still found.
 */
export async function listDescendantIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const collected: Issue[] = [];
  let frontier: IssueId[] = [issueId];
  const seen = new Set<string>([issueId]);

  while (frontier.length > 0) {
    const rows = getDb()
      .select()
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.parentId, frontier),
        ),
      )
      .orderBy(asc(issues.createdAt), asc(issues.number))
      .all();

    frontier = [];
    for (const row of rows) {
      if (seen.has(row.id)) continue;
      seen.add(row.id);
      collected.push(toIssue(row));
      frontier.push(row.id as IssueId);
    }
  }

  return collected;
}

export async function setIssueParentId(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/**
 * Archives every still-live id in one patch. Rows that are already archived
 * are not in the `WHERE`, so their timestamps stay exactly as they were.
 */
export async function archiveLiveIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...issueIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning()
    .all();

  return rows.map((row) => toIssue(row));
}

export async function archiveIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {

