  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, issueId);
}

/** Open and closed counts for every non-archived issue below this one. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const descendants = await issueRepo.listDescendantIssues(orgId, issueId);
  return rollupOf(descendants);
}

/**
 * A parent must be a live issue of the same project. Another project or
 * workspace is indistinguishable from a missing id; an archived one conflicts.
 */
async function requireSameProjectParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/** True when `targetId` is `start` or sits above it. */
async function parentChainContains(
  orgId: OrgId,
  start: Issue,
  targetId: IssueId,
): Promise<boolean> {
  let current: Issue | null = start;
  const seen = new Set<string>();
  while (current !== null) {
    if (current.id === targetId) return true;
    if (seen.has(current.id)) return false;
    seen.add(current.id);
    if (current.parentId === null) return false;
    current = await issueRepo.findIssueById(orgId, current.parentId);
  }
  return false;
}

/** Level of an issue already in the tree. A root is 0. */
async function ancestorLevel(orgId: OrgId, issue: Issue): Promise<number> {
  let level = 0;
  let parentId = issue.parentId;
  const seen = new Set<string>([issue.id]);
  while (parentId !== null) {
    if (seen.has(parentId)) break;
    seen.add(parentId);
    const parent = await issueRepo.findIssueById(orgId, parentId);
    if (parent === null) break;
    level += 1;
    parentId = parent.parentId;
  }
  return level;
}

/**
 * How many steps down the deepest descendant sits. Archived rows count: they
 * move with the issue and must not be buried past the depth cap.
 */
function subtreeHeight(rootId: IssueId, descendants: readonly Issue[]): number {
  const childIds = new Map<string, IssueId[]>();
  for (const descendant of descendants) {
    if (descendant.parentId === null) continue;
    const siblings = childIds.get(descendant.parentId);
    if (siblings === undefined) {
      childIds.set(descendant.parentId, [descendant.id]);
    } else {
      siblings.push(descendant.id);
    }
  }

  const seen = new Set<string>();
  function height(id: string): number {
    if (seen.has(id)) return 0;
    seen.add(id);
    let max = 0;
    for (const childId of childIds.get(id) ?? []) {
      const childHeight = 1 + height(childId);
      if (childHeight > max) max = childId ? childHeight : childHeight;
    }
    return max;
  }

  return height(rootId);
}

async function assertPlacement(
  orgId: OrgId,
  issue: Issue,
  parent: Issue | null,
): Promise<void> {
  if (parent !== null && (await parentChainContains(orgId, parent, issue.id))) {
    throw new IssueHierarchyError(issue.id, "cycle");
  }

  const descendants = await issueRepo.listDescendantIssues(orgId, issue.id);
  const height = subtreeHeight(issue.id, descendants);
  const level = parent === null ? 0 : (await ancestorLevel(orgId, parent)) + 1;
  if (level + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issue.id, "too_deep");
  }
}

function rollupOf(descendants: readonly Issue[]): IssueRollup {
  let total = 0;
  let open = 0;
  let closed = 0;
  for (const descendant of descendants) {
    if (descendant.archivedAt !== null) continue;
    total += 1;
    if (CLOSED_ISSUE_STATUSES.includes(descendant.status)) closed += 1;
    else open += 1;
  }
  return { total, open, closed };
}

