 * null. Sub-issues stay attached, so the depth check uses the deepest
 * descendant. A refusal writes nothing and announces nothing.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const parent =
    input.parentId === null
      ? null
      : await requireSameProjectParent(
          input.orgId,
          issue.projectId,
          input.parentId,
        );

  if (issue.parentId === input.parentId) return issue;

  await assertPlacement(input.orgId, issue, parent);

  const after = await issueRepo.setIssueParentId(
    input.orgId,
    issue.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

