import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notificationResource, requireFound } from "./_support";

subscribe("issue.status_changed", async (payload) => {
  const wasOpen = !CLOSED_ISSUE_STATUSES.includes(payload.from);
  const nowClosed = CLOSED_ISSUE_STATUSES.includes(payload.to);
  if (!wasOpen || !nowClosed) return;

  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  if (!issue) return;
  await notifyParentIfSubIssuesCompleted(
    payload.orgId,
    issue.parentId,
    payload.actorId,
  );
});

subscribe("issue.archived", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  // Archiving a closed issue is not a closing: it was already not open.
  if (!issue || CLOSED_ISSUE_STATUSES.includes(issue.status)) return;
  await notifyParentIfSubIssuesCompleted(
    payload.orgId,
    issue.parentId,
    payload.actorId,
  );
});

subscribe("issue.assigned", async (payload) => {

/**
 * Tells the direct parent's assignee, once, when that parent is left with no
 * open issue below it. Preferences and the actor-skip live in `notify`.
 * Nothing is sent for an unassigned or archived parent, or one with no
 * sub-issues at all.
 */
async function notifyParentIfSubIssuesCompleted(
  orgId: OrgId,
  parentId: IssueId | null,
  actorId: UserId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const descendants = await issueRepo.listDescendantIssues(orgId, parent.id);
  if (descendants.length === 0) return;

  const stillOpen = descendants.some(
    (descendant) =>
      descendant.archivedAt === null &&
      !CLOSED_ISSUE_STATUSES.includes(descendant.status),
  );
  if (stillOpen) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `Every sub-issue under "${parent.title}" is complete`,
    href: `/issues/${parent.id}`,
    actorId,
  });
}

registerFanOut();

