import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { isDomainError, toAppError } from "@/lib/errors";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("hier");
  other = await createTenant("hierother");
});

afterAll(() => cleanup());

async function make(
  title: string,
  parentId: string | null = null,
  assigneeId: string | null = null,
): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, { title }),
    parentId: parentId as never,
    assigneeId: assigneeId as never,
  });
}

describe("issue hierarchy", () => {
  it("covers the tree rules", async () => {
    const root = await make("root", null, tenant.userIds.admin);
    const child = await make("child", root.id);
    const grand = await make("grand", child.id);
    const great = await make("great", grand.id);

    await expect(make("too deep", great.id)).rejects.toMatchObject({
      reason: "too_deep",
      code: "conflict",
    });
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(4);

    const created: unknown[] = [];
    const offCreated = subscribe("issue.created", (payload) => {
      created.push(payload);
    });
    const archivedParent = await make("archived parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedParent.id);
    await expect(make("under archived", archivedParent.id)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
    offCreated();
    expect(created).toHaveLength(0);

    const otherIssue = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "elsewhere" }),
    );
    await expect(make("cross", otherIssue.id)).rejects.toBeInstanceOf(NotFoundError);

    const project2 = await (await import("@/server/services/project-service")).createProject(
      tenant.actors.admin,
      {
        orgId: tenant.org.id,
        name: "Other",
        slug: "other-proj",
        key: "OTH",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#000000",
        targetDate: null,
      },
    );
    const foreign = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project2.id, { title: "foreign project" }),
    );
    await expect(make("cross project", foreign.id)).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.setIssueParent(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.listSubIssues(tenant.actors.member, other.org.id, root.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const events: { id: string; fields: readonly string[] }[] = [];
    const off = subscribe("issue.updated", (payload) => {
      events.push({ id: payload.issueId, fields: payload.changedFields });
    });
    const moved = await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: grand.id,
      parentId: root.id,
    });
    expect(moved.parentId).toBe(root.id);
    expect(events).toEqual([{ id: grand.id, fields: ["parentId"] }]);

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: root.id,
        parentId: great.id,
      }),
    ).rejects.toMatchObject({ reason: "cycle", issueId: root.id });
    expect(
      (await issueRepo.findIssueById(tenant.org.id, root.id))?.parentId,
    ).toBeNull();

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: child.id,
      }),
    ).rejects.toMatchObject({ reason: "cycle" });

    const deep = await make("deep root");
    const d1 = await make("d1", deep.id);
    const d2 = await make("d2", d1.id);
    const d3 = await make("d3", d2.id);
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: deep.id,
        parentId: great.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep", issueId: deep.id });
    expect(
      (await issueRepo.findIssueById(tenant.org.id, deep.id))?.parentId,
    ).toBeNull();
    expect(
      (await issueRepo.findIssueById(tenant.org.id, d3.id))?.parentId,
    ).toBe(d2.id);

    const listed = await issueService.listSubIssues(
      tenant.actors.viewer,
      tenant.org.id,
      root.id,
    );
    expect(listed.map((issue) => issue.id)).toEqual([child.id, grand.id]);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: grand.id,
      status: "done",
    });
    const rollup = await issueService.getIssueRollup(
      tenant.actors.viewer,
      tenant.org.id,
      root.id,
    );
    expect(rollup).toEqual({ total: 3, open: 2, closed: 1 });

    const archivedEvents: string[] = [];
    const offArchived = subscribe("issue.archived", (payload) => {
      archivedEvents.push(payload.issueId);
    });
    const already = await make("already", child.id);
    await issueRepo.archiveIssue(tenant.org.id, already.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);
    offArchived();
    expect(archivedEvents).toContain(child.id);
    expect(archivedEvents).toContain(great.id);
    expect(archivedEvents).not.toContain(already.id);
    expect(
      (await issueRepo.findIssueById(tenant.org.id, already.id))?.archivedAt,
    ).not.toBeNull();
    expect(
      (await issueRepo.findIssueById(tenant.org.id, root.id))?.archivedAt,
    ).toBeNull();

    const hierarchy = new IssueHierarchyError("abc", "cycle");
    expect(isDomainError(hierarchy)).toBe(true);
    expect(toAppError(hierarchy).code).toBe("conflict");

    off();
  });

  it("notifies the parent assignee once when the last open sub-issue closes", async () => {
    const parent = await make("notify parent", null, tenant.userIds.owner);
    const a = await make("open a", parent.id);
    const b = await make("open b", parent.id);

    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: a.id,
      status: "done",
    });

    const first = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(first.items.filter((item) => item.kind === "sub_issues_completed")).toHaveLength(
      0,
    );

    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: b.id,
      status: "canceled",
    });

    const second = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    const notes = second.items.filter((item) => item.kind === "sub_issues_completed");
    expect(notes).toHaveLength(1);
    expect(notes[0]?.actorId).toBe(tenant.userIds.admin);

    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: b.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: b.id,
      status: "done",
    });
    const third = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(
      third.items.filter((item) => item.kind === "sub_issues_completed"),
    ).toHaveLength(2);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.owner,
      kind: "sub_issues_completed",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    const leaf = await make("muted leaf", parent.id);
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: b.id,
      status: "todo",
    });
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, leaf.id);
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: b.id,
      status: "done",
    });
    const muted = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 50,
      cursor: null,
    });
    expect(
      muted.items.filter((item) => item.kind === "sub_issues_completed"),
    ).toHaveLength(2);

    const self = await make("self parent", null, tenant.userIds.admin);
    const selfChild = await make("self child", self.id);
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: selfChild.id,
      status: "done",
    });
    const adminNotes = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(
      adminNotes.items.filter((item) => item.kind === "sub_issues_completed"),
    ).toHaveLength(0);
  });
});

